UPDATE positions SET stance = 'support', confidence = 'inferred', rationale = 'Gianaris has been strongly pro-Israel in legislative action, spearheading anti-BDS legislation and calling for increased security funding for Jewish and Muslim schools after Oct 7. He has framed BDS as fueling antisemitism while also addressing Islamophobia.', summary = 'Spearheaded NY anti-BDS law, stating BDS movement "gives legitimacy to anti-Semitic incidents" (https://www.timesofisrael.com/ny-state-senator-pushes-bill-with-teeth-to-combat-bds/). Led effort with 80+ legislators to double security funding at Jewish and Muslim schools in response to post-Oct 7 hate (https://www.nysenate.gov/newsroom/press-releases/2023/michael-gianaris/senate-deputy-leader-gianaris-assembly-member-hevesi). Called to "combat the increasing dual threats of Antisemitism and Islam', updated_at = NOW() WHERE person_id = 12 AND topic_id = (SELECT id FROM topics WHERE slug = 'israel') AND assessment_type = 'ai';
UPDATE positions SET stance = 'support', confidence = 'inferred', rationale = 'Comrie has engaged with Jewish institutions in his district and condemned antisemitic attacks. He met with Queens yeshivah principals and joined a joint statement condemning an antisemitic attack on a rabbi on Holocaust Remembrance Day.', summary = 'Met with Queens yeshivah principals to discuss Jewish education issues (https://www.queensjewishlink.com/index.php/local/26-community-corner/7052-queens-yeshivah-principals-meet-state-senator-leroy-comrie). Joined joint statement condemning antisemitic attack on rabbi in Queens on Holocaust Remembrance Day Jan 2026, calling it "a targeted act of hate" (https://combatantisemitism.org/cam-news/rabbi-attacked-in-queens-on-international-holocaust-remembrance-day/).', updated_at = NOW() WHERE person_id = 14 AND topic_id = (SELECT id FROM topics WHERE slug = 'israel') AND assessment_type = 'ai';
UPDATE positions SET stance = 'support', confidence = 'inferred', rationale = 'Gounardes has publicly condemned anti-Israel graffiti as antisemitism and defended Jewish community members in Brooklyn. Called vandalism of Israeli restaurant "antisemitism plain and simple" and a "clear example of when anti-Zionism becomes antisemitism."', summary = 'Called anti-Israel graffiti on Park Slope restaurant Miriam "antisemitism plain and simple," stating it "fosters the growing feeling that Jewish people are not welcome here" and "vandalizing the restaurant because they serve Israeli food and their owner is Jewish is a clear example of when anti-Zionism becomes antisemitism" (https://brooklyneagle.com/articles/2025/01/27/anti-israel-graffiti-sprayed-on-park-slope-restaurant-miriam/). Earlier in career, connected antisemitic vandalism at a synagog', updated_at = NOW() WHERE person_id = 26 AND topic_id = (SELECT id FROM topics WHERE slug = 'israel') AND assessment_type = 'ai';
UPDATE positions SET stance = 'support', confidence = 'inferred', rationale = 'Hinchey, who is Jewish on her mother''s side, spoke at a "Stand with Israel" prayer service days after Oct 7 attacks. She expressed solidarity with the Jewish community while also condemning anti-Palestinian hate. Has not publicly called for ceasefire.', summary = 'Spoke at "Stand With Israel" prayer service at Congregation Emanuel on Oct 18, 2023, saying "My heart breaks for my Jewish peers. We are bonded in that shared trauma" (https://hudsonvalleyone.com/2023/10/19/stand-with-israel-prayer-service-at-congregation-emanuel/). Jewish on her mother''s side, grew up attending High Holiday services. As of March 2024, had not weighed in on ceasefire calls (https://www.cityandstateny.com/politics/2024/03/new-york-elected-officials-calling-ceasefire-gaza/394535/)', updated_at = NOW() WHERE person_id = 41 AND topic_id = (SELECT id FROM topics WHERE slug = 'israel') AND assessment_type = 'ai';
UPDATE positions SET stance = 'support', confidence = 'inferred', rationale = 'As a member of the NY Senate Republican Conference, Stec participated in the conference''s call to deploy the National Guard to Columbia University to protect Jewish students from pro-Hamas protests. He is specifically named in the conference''s Columbia statement.', summary = 'Named as a signer of the Senate Republican Conference letter calling on Governor Hochul to deploy National Guard to Columbia to protect Jewish students, April 2024 (https://www.nysenate.gov/newsroom/press-releases/2024/andrew-j-lanza/members-new-york-state-senate-republican-conference). Part of conference that unveiled antisemitism report and legislation package.', updated_at = NOW() WHERE person_id = 45 AND topic_id = (SELECT id FROM topics WHERE slug = 'israel') AND assessment_type = 'ai';
UPDATE positions SET stance = 'support', confidence = 'inferred', rationale = 'Republican and US Army Reserve Captain who was deployed to the Middle East (Kuwait) for 290 days in 2024, overseeing military construction projects across Kuwait, Jordan, Saudi Arabia, Syria, and Iraq. His military service in the region and Republican conference membership suggest pro-Israel alignment, though no explicit Israel statement found.', summary = 'Deployed to Middle East Jan 2024 for ~290 days as Army Reserve Captain, served as construction Portfolio Manager for Task Force Castle across Kuwait, Jordan, Saudi Arabia, Syria, Iraq (https://www.nysenate.gov/newsroom/press-releases/2024/mark-walczyk/senator-walczyk-returns-home). Member of Senate Republican Conference. Missed 2024 session due to deployment.', updated_at = NOW() WHERE person_id = 49 AND topic_id = (SELECT id FROM topics WHERE slug = 'israel') AND assessment_type = 'ai';
UPDATE positions SET stance = 'strongly_support', confidence = 'inferred', rationale = 'Borrello has been vocal in condemning pro-Hamas protests, calling for action against antisemitism at Columbia, and criticizing "DSA radicals" for antisemitic rhetoric. Signed Columbia National Guard letter and participated in Senate Republican Conference antisemitism initiatives.', summary = 'Named signer of Senate Republican Conference letter calling for National Guard at Columbia to protect Jewish students (https://www.nysenate.gov/newsroom/press-releases/2024/andrew-j-lanza/members-new-york-state-senate-republican-conference). Called on Hochul to take "swift and decisive action against antisemitic mobs" and stated "the rights and safety of Jewish students must be restored." Criticized "the recent rise in antisemitic rhetoric coming from DSA radicals at all levels of government." P', updated_at = NOW() WHERE person_id = 57 AND topic_id = (SELECT id FROM topics WHERE slug = 'israel') AND assessment_type = 'ai';
